// Code généré depuis les registres publics IEEE OUI (MA-L + MA-M + MA-S).
// NE PAS ÉDITER À LA MAIN — régénérer via le générateur documenté au CHANGELOG N°197.
//
// N°197 — marque probable d'un appareil depuis le préfixe constructeur (OUI)
// de son adresse MAC. Couverture volontairement bornée aux fabricants
// PERTINENTS pour la console hotspot (smartphones et ordinateurs des clients,
// box et routeurs du parc — focus Afrique de l'Ouest où dominent Tecno,
// Infinix, itel, Samsung, Xiaomi et Huawei) : un préfixe hors table = marque
// inconnue (affichée « — »), jamais une déduction risquée. La marque reste un
// INDICE (carte réseau remplacée, virtualisation, préfixe revendu) : l'UI la
// libelle « marque probable ».
package api

// ouiVendors — préfixe hexa (MAJUSCULES, sans séparateur) -> marque.
// Registres du 2026-10-01 : oui.csv (MA-L 24 bits, 6 hex), mam.csv (MA-M
// 28 bits, 7 hex), oui36.csv (MA-S 36 bits, 9 hex). Résolution par longueur
// décroissante (voir macVendor) : le préfixe le plus spécifique gagne.
